def letter_grade(percent):
    """Convert a percentage to a letter grade.

    Args:
        percent: The percentage score (float or None)

    Returns:
        The letter grade (str) or "-" if percent is None
    """
    if percent is None:
        return "-"
    elif percent >= 90:
        return "A"
    elif percent >= 80:
        return "B"
    elif percent >= 70:
        return "C"
    elif percent >= 60:
        return "D"
    else:
        return "F"

